                    gs=f+start*3; ge=f+j*3  # 0-based within this seq
                    out.append((gs,ge,len(aa),aa))
                aa=""; start=j+1
            else: aa+=ch
        if len(aa)>=minaa:
            gs=f+start*3; ge=f+start*3+len(aa)*3
            out.append((gs,ge,len(aa),aa))
    return out

