seq=""
for line in open("region.fasta"):
    if not line.startswith(">"): seq+=line.strip()
n=len(seq)
from collections import defaultdict
k=16
d=defaultdict(list)
for i in range(n-k+1):
    d[seq[i:i+k]].append(i)
matches=[]
for w,ps in d.items():
    if len(ps)>1:
        for a in range(len(ps)):
            for b in range(a+1,len(ps)):
                matches.append((ps[a],ps[b]))
# extend each seed
seen=set()
res=[]
for a,b in matches:
    if (a,b) in seen: continue
    # extend
    l=k
    while a+l<n and b+l<n and seq[a+l]==seq[b+l]: l+=1
    e=0
    while a-e-1>=0 and b-e-1>=0 and seq[a-e-1]==seq[b-e-1]: e+=1
    s1=a-e; s2=b-e; L=l+e
    seen.add((a,b))
    if L>=24 and s2-s1>10:
        res.append((s1,s2,L))
res=sorted(set(res))
# collapse overlapping duplicates
out=[]
for s1,s2,L in res:
    if out and abs(s1-out[-1][0])<=3 and abs(s2-out[-1][1])<=3:
        continue
    out.append((s1,s2,L))
print("Direct repeats >=24 bp (positions 1-based):")
for s1,s2,L in out:
    print(f"  {s1+1:4d} <-> {s2+1:4d}   len {L:3d}   {seq[s1:s1+40]}")
